:root {
  color-scheme: light;
  --ink: #202b3c;
  --muted: #758198;
  --paper: #fffdf7;
  --line: #e7e5dc;
  --mint: #c8f2df;
  --green: #246d58;
  --peach: #ffcfb8;
  --navy: #26374c;
}

* { box-sizing: border-box; }
body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #dff3e9;
  background-image: linear-gradient(45deg, rgba(38,55,76,.045) 25%, transparent 25%, transparent 75%, rgba(38,55,76,.045) 75%), linear-gradient(45deg, rgba(38,55,76,.045) 25%, transparent 25%, transparent 75%, rgba(38,55,76,.045) 75%);
  background-position: 0 0, 12px 12px;
  background-size: 24px 24px;
  color: var(--ink);
  font: 16px/1.45 system-ui, sans-serif;
}
button, input { font: inherit; }
.board {
  width: min(100%, 760px);
  padding: clamp(22px, 5vw, 42px);
  background: var(--paper);
  border: 3px solid var(--navy);
  box-shadow: 8px 8px 0 var(--navy);
}
.header, .section-heading { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
.eyebrow { margin: 0 0 6px; color: var(--green); font-size: 13px; font-weight: 800; letter-spacing: .14em; }
h1 { margin: 0; font-size: clamp(30px, 7vw, 42px); line-height: 1.1; letter-spacing: -.04em; }
.count { min-width: 76px; padding: 10px 12px; display: grid; justify-items: center; border: 2px solid var(--navy); background: var(--mint); font-weight: 800; line-height: 1.15; }
.count span:first-child { font-size: 23px; }
.count span:last-child { font-size: 12px; letter-spacing: .12em; }
.alarm-form { margin-top: 30px; padding: 20px; border: 2px solid var(--line); background: #faf9f3; }
fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }
legend { margin-bottom: 14px; font-size: 18px; font-weight: 750; }
.form-row { display: flex; align-items: end; gap: 12px; }
.time-field, .label-field { display: grid; gap: 6px; }
.time-field { width: 78px; flex: 0 0 78px; }
.label-field { min-width: 100px; flex: 1; }
.time-field span, .label-field > span { color: var(--muted); font-size: 13px; font-weight: 700; }
input { width: 100%; min-width: 0; height: 48px; padding: 0 11px; border: 2px solid #d7d8cf; border-radius: 0; background: white; color: var(--ink); }
input::placeholder { color: #a1a8b1; }
input:focus-visible, button:focus-visible { outline: 3px solid #dc805b; outline-offset: 3px; }
.colon { align-self: center; margin-top: 24px; font-size: 24px; font-weight: 800; }
.optional { font-weight: 500; }
button { min-height: 48px; padding: 0 16px; border: 2px solid var(--navy); background: var(--navy); color: white; font-weight: 750; cursor: pointer; transition: transform .12s, box-shadow .12s, background .12s; }
button:hover { background: var(--green); box-shadow: 3px 3px 0 var(--navy); transform: translate(-1px, -1px); }
button:active { box-shadow: none; transform: translate(2px, 2px); }
.add-button span { margin-left: 5px; font-size: 21px; vertical-align: -1px; }
.alarms-section { margin-top: 30px; }
.section-heading { padding-bottom: 12px; border-bottom: 2px solid var(--navy); }
h2 { margin: 0; font-size: 21px; }
#alarm-total { color: var(--muted); font-size: 14px; font-weight: 650; }
.alarm-list { margin: 0; padding: 0; list-style: none; }
.alarm-item { min-height: 78px; display: flex; align-items: center; gap: 14px; padding: 14px 2px; border-bottom: 1px solid var(--line); }
.alarm-time { min-width: 112px; font-size: 27px; font-weight: 800; font-variant-numeric: tabular-nums; letter-spacing: .03em; }
.alarm-details { min-width: 0; flex: 1; }
.alarm-name { overflow-wrap: anywhere; font-weight: 700; }
.alarm-status { margin-top: 2px; color: var(--muted); font-size: 13px; }
.alarm-item.is-off .alarm-time, .alarm-item.is-off .alarm-name { color: #8991a0; }
.toggle-button { min-width: 70px; min-height: 40px; padding: 0 10px; border-color: var(--green); background: var(--mint); color: var(--green); }
.toggle-button[aria-pressed="false"] { border-color: #8991a0; background: #f0f0eb; color: #596476; }
.delete-button { min-width: 42px; min-height: 40px; padding: 0 9px; border-color: #e7b9a7; background: #fff3ec; color: #8a4932; }
.delete-button:hover { border-color: var(--navy); background: var(--peach); }
.empty-state { margin: 0; padding: 28px 12px; color: var(--muted); text-align: center; }
footer { margin-top: 28px; color: var(--muted); font-size: 12px; font-weight: 800; letter-spacing: .13em; text-align: center; }
footer span { color: var(--green); }

@media (max-width: 600px) {
  body { padding: 20px 14px; }
  .form-row { display: grid; grid-template-columns: 72px 18px 72px; gap: 10px; }
  .time-field { width: auto; }
  .label-field, .add-button { grid-column: 1 / -1; }
  .label-field { margin-top: 2px; }
  .colon { margin-top: 24px; }
  .alarm-form { padding: 16px; }
  .alarm-item { gap: 9px; }
  .alarm-time { min-width: 84px; font-size: 23px; }
  .toggle-button { min-width: 62px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; }
}

const form = document.querySelector('#alarm-form');
const hourInput = document.querySelector('#hour');
const minuteInput = document.querySelector('#minute');
const labelInput = document.querySelector('#label');
const alarmList = document.querySelector('#alarm-list');
const enabledCount = document.querySelector('#enabled-count');
const alarmTotal = document.querySelector('#alarm-total');
const emptyState = document.querySelector('#empty-state');

let nextId = 1;
let alarms = [];

function render() {
  alarms.sort((a, b) => a.hour - b.hour || a.minute - b.minute || a.id - b.id);
  alarmList.replaceChildren();

  for (const alarm of alarms) {
    const item = document.createElement('li');
    item.className = `alarm-item${alarm.enabled ? '' : ' is-off'}`;

    const time = document.createElement('time');
    const hour = String(alarm.hour).padStart(2, '0');
    const minute = String(alarm.minute).padStart(2, '0');
    time.className = 'alarm-time';
    time.dateTime = `${hour}:${minute}`;
    time.textContent = `${hour}:${minute}`;

    const details = document.createElement('div');
    details.className = 'alarm-details';
    const name = document.createElement('div');
    name.className = 'alarm-name';
    name.textContent = alarm.label || 'Alarm';
    const status = document.createElement('div');
    status.className = 'alarm-status';
    status.textContent = alarm.enabled ? 'Enabled' : 'Off';
    details.append(name, status);

    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.className = 'toggle-button';
    toggle.textContent = alarm.enabled ? 'On' : 'Off';
    toggle.setAttribute('aria-label', `${alarm.enabled ? 'Turn off' : 'Turn on'} ${hour}:${minute}${alarm.label ? `, ${alarm.label}` : ' alarm'}`);
    toggle.setAttribute('aria-pressed', String(alarm.enabled));
    toggle.addEventListener('click', () => {
      alarm.enabled = !alarm.enabled;
      render();
    });

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.textContent = '×';
    remove.setAttribute('aria-label', `Delete ${hour}:${minute}${alarm.label ? `, ${alarm.label}` : ' alarm'}`);
    remove.addEventListener('click', () => {
      alarms = alarms.filter(entry => entry.id !== alarm.id);
      render();
    });

    item.append(time, details, toggle, remove);
    alarmList.append(item);
  }

  const active = alarms.filter(alarm => alarm.enabled).length;
  enabledCount.textContent = String(active);
  alarmTotal.textContent = `${alarms.length} ${alarms.length === 1 ? 'alarm' : 'alarms'}`;
  emptyState.hidden = alarms.length > 0;
}

form.addEventListener('submit', event => {
  event.preventDefault();
  if (!form.reportValidity()) return;

  const hour = Number(hourInput.value);
  const minute = Number(minuteInput.value);
  if (!Number.isInteger(hour) || hour < 0 || hour > 23 || !Number.isInteger(minute) || minute < 0 || minute > 59) return;

  alarms.push({
    id: nextId++,
    hour,
    minute,
    label: labelInput.value.trim(),
    enabled: true
  });
  form.reset();
  render();
  hourInput.focus();
});

render();
